@IsTest
private class NestedConstructorObservation {
    private static void emit(Map<String,Object> row) {
        row.put('branchCalls',OwnedBranch.calls);
        row.put('baseCalls',OwnedNestBase.calls);
        row.put('leafCalls',OwnedNestLeaf.leafCalls);
        System.assertEquals('capture','NESTED_CONSTRUCTOR_OBSERVATION '+JSON.serialize(row));
    }
    private static void failure(Map<String,Object> row,Exception issue) {
        row.put('exceptionType',issue.getTypeName());
        row.put('exceptionMessage',issue.getMessage());
    }
    @IsTest static void finiteBranch() {
        Map<String,Object> row=new Map<String,Object>{'stage'=>'construct'};
        try {
            OwnedBranch root=new OwnedBranch('root',new List<String>{'left','right'});
            row.put('stage','readFields');
            row.put('root',root.label);
            row.put('labels',new List<String>{root.children[0].label,root.children[1].label});
            row.put('leafSizes',new List<Integer>{root.children[0].children.size(),root.children[1].children.size()});
            row.put('distinct',root!==root.children[0] && root.children[0]!==root.children[1]);
            row.put('stage','complete');
        } catch(Exception issue) { failure(row,issue); }
        emit(row);
    }
    @IsTest static void inheritedBase() {
        Map<String,Object> row=new Map<String,Object>{'stage'=>'construct'};
        try {
            OwnedNestLeaf root=new OwnedNestLeaf(2);
            row.put('stage','readFields');
            row.put('depths',new List<Integer>{root.depth,root.child.depth,root.child.child.depth});
            row.put('terminalNull',root.child.child.child==null);
            row.put('distinct',root!==root.child && root.child!==root.child.child);
            row.put('stage','complete');
        } catch(Exception issue) { failure(row,issue); }
        emit(row);
    }
    @IsTest static void siblingAndSequential() {
        Map<String,Object> row=new Map<String,Object>{'stage'=>'firstConstruct'};
        try {
            OwnedBranch first=new OwnedBranch('first',new List<String>{'left','right'});
            row.put('stage','secondConstruct');
            OwnedBranch second=new OwnedBranch('second',new List<String>{'other'});
            row.put('stage','mutateFirstSibling');
            first.children[0].label='changed';
            first.children[0].children.add(new OwnedBranch('extra'));
            row.put('labels',new List<String>{first.children[0].label,first.children[1].label,second.children[0].label});
            row.put('sizes',new List<Integer>{first.children[0].children.size(),first.children[1].children.size(),second.children[0].children.size()});
            row.put('distinctRoots',first!==second);
            row.put('stage','complete');
        } catch(Exception issue) { failure(row,issue); }
        emit(row);
    }
    @IsTest static void emptyAndSequentialControls() {
        Map<String,Object> row=new Map<String,Object>{'stage'=>'emptyBranch'};
        try {
            OwnedBranch branch=new OwnedBranch('empty',new List<String>());
            row.put('stage','oneArgEmptyBranch');
            OwnedBranch other=new OwnedBranch('other');
            row.put('stage','firstLeaf');
            OwnedNestLeaf first=new OwnedNestLeaf(0);
            row.put('stage','secondLeaf');
            OwnedNestLeaf second=new OwnedNestLeaf(0);
            row.put('branchSizes',new List<Integer>{branch.children.size(),other.children.size()});
            row.put('depths',new List<Integer>{first.depth,second.depth});
            row.put('bothTerminal',first.child==null && second.child==null);
            row.put('distinct',branch!==other && first!==second);
            row.put('stage','complete');
        } catch(Exception issue) { failure(row,issue); }
        emit(row);
    }
}

