public class OwnedBranch {
    public static Integer calls=0;
    public String label;
    public List<OwnedBranch> children=new List<OwnedBranch>();
    public OwnedBranch(String label) {
        this(label,new List<String>());
    }
    public OwnedBranch(String label,List<String> names) {
        this.label=label;
        calls++;
        for(String childName:names) {
            children.add(new OwnedBranch(childName));
        }
    }
}

public virtual class OwnedNestBase {
    public static Integer calls=0;
    public Integer depth;
    public OwnedNestBase child;
    public OwnedNestBase(Integer depth) {
        this(depth,true);
    }
    public OwnedNestBase(Integer depth,Boolean marker) {
        this.depth=depth;
        calls++;
        if(depth>0) {
            child=new OwnedNestLeaf(depth-1);
        }
    }
}

public class OwnedNestLeaf extends OwnedNestBase {
    public static Integer leafCalls=0;
    public OwnedNestLeaf(Integer depth) {
        super(depth);
        leafCalls++;
    }
}

